package os.aios.agent;
import org.json.*;import java.util.*;
public final class NativeThreadPagerTest{
 static void check(boolean v){if(!v)throw new AssertionError();}
 public static void main(String[] a)throws Exception{ArrayList<String> calls=new ArrayList<>();NativeThreadPager pager=new NativeThreadPager((method,p)->{calls.add(method+":"+p.optInt("limit"));if(method.equals("thread/read")){check(!p.getBoolean("includeTurns"));return new JSONObject().put("thread",new JSONObject().put("id","t"));}if(method.equals("thread/turns/list"))return new JSONObject().put("data",new JSONArray().put(new JSONObject().put("id","u").put("status","completed"))).put("nextCursor","older").put("backwardsCursor","newer");JSONArray entries=new JSONArray();for(int i=0;i<64;i++)entries.put(new JSONObject().put("turnId","u").put("item",new JSONObject().put("id","i"+i).put("type","agentMessage").put("text","x")));return new JSONObject().put("data",entries).put("nextCursor","older-items").put("backwardsCursor","newer-items");});JSONObject current=pager.current("t","u");JSONObject turn=current.getJSONArray("turns").getJSONObject(0);check(turn.getJSONArray("items").length()==64);check(turn.getBoolean("items_has_older"));check(calls.size()==2);check(calls.get(0).equals("thread/turns/list:1"));check(calls.get(1).equals("thread/items/list:64"));JSONObject recent=pager.recent("t",12);check(recent.getJSONObject("history_page").getBoolean("has_older"));check(recent.getJSONObject("history_page").getString("next_cursor").equals("older"));NativeThreadPager complete=new NativeThreadPager((method,p)->method.equals("thread/turns/list")?new JSONObject().put("data",new JSONArray().put(new JSONObject().put("id","u").put("status","completed"))).put("nextCursor",JSONObject.NULL):new JSONObject().put("data",new JSONArray().put(new JSONObject().put("item",new JSONObject().put("id","final").put("type","agentMessage").put("phase","final_answer").put("text","done")))).put("nextCursor",JSONObject.NULL));JSONObject full=complete.current("t","u").getJSONArray("turns").getJSONObject(0);check(full.getString("itemsView").equals("full"));check(MinutesTurnResult.reply(full).equals("done"));System.out.println("NativeThreadPagerTest passed");}
}
